// lib/stig/catalog.ts
var SOURCES = [
  { benchmark: "Cisco IOS Router NDM STIG v3r5", rules: cisco_ios_router_ndm_v3r5_controls_default },
  { benchmark: "Cisco IOS Router RTR STIG v3r4", rules: cisco_ios_router_rtr_v3r4_controls_default },
  { benchmark: "Cisco IOS Switch L2S STIG v3r1", rules: cisco_ios_switch_l2s_v3r1_controls_default },
  { benchmark: "Cisco IOS Switch NDM STIG v3r5", rules: cisco_ios_switch_ndm_v3r5_controls_default },
  { benchmark: "Cisco IOS Switch RTR STIG v3r2", rules: cisco_ios_switch_rtr_v3r2_controls_default },
  { benchmark: "Cisco ISE NAC STIG v2r2", rules: cisco_ise_nac_v2r2_controls_default },
  { benchmark: "Cisco ISE NDM STIG v2r2", rules: cisco_ise_ndm_v2r2_controls_default },
  { benchmark: "Cisco NX-OS Switch L2S STIG v3r2", rules: cisco_nxos_switch_l2s_v3r2_controls_default },
  { benchmark: "Cisco NX-OS Switch NDM STIG v3r5", rules: cisco_nxos_switch_ndm_v3r5_controls_default },
  { benchmark: "Cisco NX-OS Switch RTR STIG v3r3", rules: cisco_nxos_switch_rtr_v3r3_controls_default },
  { benchmark: "Ubuntu 22.04 LTS STIG v2r6", rules: ubuntu2204_v2r6_controls_default },
  { benchmark: "RHEL 8 STIG v2r5", rules: rhel8_v2r5_controls_default },
  { benchmark: "RHEL 9 STIG v2r6", rules: rhel9_v2r6_controls_default },
  { benchmark: "Windows 11 STIG v2r5", rules: windows11_v2r5_controls_default },
  { benchmark: "Windows Server 2022 STIG v2r6", rules: windows2022_v2r6_controls_default }
];
var stripXccdf = (text) => text.replace(/<\/?VulnDiscussion>/g, "").replace(/<\/?[A-Za-z]+[^>]*>/g, " ").replace(/\s+/g, " ").trim();
var STIG_CATALOG = SOURCES.flatMap(
  ({ benchmark, rules }) => rules.map((r) => ({ ...r, description: stripXccdf(r.description), benchmark }))
);
var STIG_BY_SV_ID = new Map(STIG_CATALOG.map((r) => [r.sv_id, r]));
var PRODUCTS = SOURCES.map(({ benchmark, rules }) => ({
  product: rules[0]?.product ?? "",
  benchmark,
  rule_count: rules.length,
  severities: rules.reduce((acc, r) => {
    acc[r.severity] = (acc[r.severity] ?? 0) + 1;
    return acc;
  }, {})
}));
var duplicateIds = STIG_CATALOG.length - new Set(STIG_CATALOG.map((r) => r.sv_id)).size;
if (duplicateIds > 0) {
  console.warn(`[stig] ${duplicateIds} duplicate sv_id values \u2014 a benchmark is registered twice`);
}
for (const source of SOURCES) {
  if (source.rules.length === 0) {
    console.warn(`[stig] ${source.benchmark} contributed no rules \u2014 dataset missing or unparsed`);
  }
}

// lib/stig/ckl.ts
function xml(text) {
  return (text ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}
function datum(attribute, data) {
  return `<STIG_DATA><VULN_ATTRIBUTE>${attribute}</VULN_ATTRIBUTE><ATTRIBUTE_DATA>${xml(data)}</ATTRIBUTE_DATA></STIG_DATA>`;
}
function vulnNumFromSvId(svId) {
  const match = svId.match(/SV-(\d+)/i);
  return match ? `V-${match[1]}` : svId;
}
var SEVERITY = { high: "high", medium: "medium", low: "low" };
function buildCkl(opts) {
  const { rules, benchmark, asset = {}, findings = [] } = opts;
  const byId2 = new Map(findings.map((f) => [f.sv_id.trim().toUpperCase(), f]));
  const vulns = rules.map((rule) => {
    const finding = byId2.get(rule.sv_id.trim().toUpperCase());
    return [
      "<VULN>",
      datum("Vuln_Num", vulnNumFromSvId(rule.sv_id)),
      datum("Severity", SEVERITY[rule.severity] ?? "medium"),
      datum("Group_Title", rule.title),
      datum("Rule_ID", rule.sv_id),
      datum("Rule_Ver", rule.sv_id),
      datum("Rule_Title", rule.title),
      datum("Vuln_Discuss", rule.description),
      datum("Check_Content", rule.check_text),
      datum("Fix_Text", rule.fix_text),
      datum("CCI_REF", rule.nist_id),
      `<STATUS>${finding?.status ?? "Not_Reviewed"}</STATUS>`,
      `<FINDING_DETAILS>${xml(finding?.finding_details)}</FINDING_DETAILS>`,
      `<COMMENTS>${xml(finding?.comments)}</COMMENTS>`,
      "<SEVERITY_OVERRIDE></SEVERITY_OVERRIDE>",
      "<SEVERITY_JUSTIFICATION></SEVERITY_JUSTIFICATION>",
      "</VULN>"
    ].join("");
  }).join("");
  const siData = (name, data) => `<SI_DATA><SID_NAME>${name}</SID_NAME><SID_DATA>${xml(data)}</SID_DATA></SI_DATA>`;
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    "<!--DISA STIG Viewer :: 2.18-->",
    "<CHECKLIST>",
    "<ASSET>",
    `<ROLE>${xml(asset.role ?? "None")}</ROLE>`,
    `<ASSET_TYPE>${xml(asset.asset_type ?? "Computing")}</ASSET_TYPE>`,
    `<HOST_NAME>${xml(asset.host_name)}</HOST_NAME>`,
    `<HOST_IP>${xml(asset.host_ip)}</HOST_IP>`,
    `<HOST_MAC>${xml(asset.host_mac)}</HOST_MAC>`,
    `<HOST_FQDN>${xml(asset.host_fqdn)}</HOST_FQDN>`,
    "<TARGET_COMMENT></TARGET_COMMENT>",
    "<TECH_AREA></TECH_AREA>",
    "<TARGET_KEY></TARGET_KEY>",
    `<WEB_OR_DATABASE>${asset.web_or_database ? "true" : "false"}</WEB_OR_DATABASE>`,
    "<WEB_DB_SITE></WEB_DB_SITE>",
    "<WEB_DB_INSTANCE></WEB_DB_INSTANCE>",
    "</ASSET>",
    "<STIGS><iSTIG><STIG_INFO>",
    siData("version", "1"),
    siData("title", benchmark),
    siData("stigid", benchmark),
    siData("description", `${benchmark} \u2014 exported by MacTech Solutions`),
    siData("releaseinfo", benchmark),
    "</STIG_INFO>",
    vulns,
    "</iSTIG></STIGS>",
    "</CHECKLIST>"
  ].join("");
}
function summarizeCkl(rules, findings = []) {
  const byId2 = new Map(findings.map((f) => [f.sv_id.trim().toUpperCase(), f]));
  const counts = {
    Open: 0,
    NotAFinding: 0,
    Not_Applicable: 0,
    Not_Reviewed: 0
  };
  for (const rule of rules) {
    counts[byId2.get(rule.sv_id.trim().toUpperCase())?.status ?? "Not_Reviewed"] += 1;
  }
  return counts;
}

// lib/mcp/servers/stig.ts
var STIG_SERVER_KEY = "stig";
var STIG_INSTRUCTIONS = `MacTech Solutions STIG server: ${STIG_CATALOG.length} DISA STIG hardening rules across RHEL 8/9, Windows 11, Windows Server 2022, and Cisco IOS Router NDM \u2014 searchable, with full check and fix text per rule and NIST control mappings. Use search_stig to find rules, get_stig_rule for implementation detail, list_stig_benchmarks for coverage, and export_stig_checklist to produce a DISA .ckl.`;
var ATTRIBUTION2 = makeAttribution(
  "DISA STIG benchmarks (XCCDF)",
  "/mcp/stig",
  "server docs and benchmark coverage",
  "stig"
);
var SERVER_KEY2 = STIG_SERVER_KEY;
var jsonResult2 = makeJsonResult(ATTRIBUTION2);
var structuredResult2 = makeStructuredResult(ATTRIBUTION2);
var RULE_OUTPUT = {
  sv_id: external_exports.string(),
  nist_id: external_exports.string().describe("CCI identifier, e.g. CCI-000366."),
  severity: external_exports.string(),
  severity_category: external_exports.string().describe("CAT I / II / III, the vocabulary assessors use."),
  title: external_exports.string(),
  description: external_exports.string(),
  check_text: external_exports.string().describe("DISA's own check procedure \u2014 quote it rather than paraphrasing."),
  fix_text: external_exports.string(),
  product: external_exports.string(),
  benchmark: external_exports.string(),
  category: external_exports.string(),
  automation_level: external_exports.string(),
  automation_source: external_exports.string()
};
var CHECKLIST_OUTPUT = {
  benchmark: external_exports.string(),
  rule_count: external_exports.number(),
  status_counts: external_exports.object({
    Open: external_exports.number(),
    NotAFinding: external_exports.number(),
    Not_Applicable: external_exports.number(),
    Not_Reviewed: external_exports.number()
  }),
  filename: external_exports.string(),
  note: external_exports.string(),
  ckl: external_exports.string().describe("The .ckl XML. Write it to filename rather than pasting it into a reply.")
};
var PRODUCT_IDS = Array.from(new Set(STIG_CATALOG.map((r) => r.product)));
var severityToCat = (severity) => severity === "high" ? "CAT I" : severity === "medium" ? "CAT II" : "CAT III";
var summarize = (r) => ({
  sv_id: r.sv_id,
  benchmark: r.benchmark,
  severity: r.severity,
  title: r.title,
  category: r.category,
  automation: r.automation_level
});
function registerStigServer(server) {
  server.registerTool(
    "search_stig",
    {
      title: "Search DISA STIG rules",
      description: "Search DISA STIG hardening rules across RHEL 8, RHEL 9, Windows 11, Windows Server 2022, and Cisco IOS Router NDM benchmarks \u2014 by keyword (matched against rule IDs and titles first, then descriptions), filterable by product, severity (high/medium/low, mapping to CAT I/II/III), category, and automation level. Call this when the user asks how to harden one of these platforms, what a STIG requires, or which rules cover a topic like SSH, passwords, or auditing. Returns summaries; use get_stig_rule for full check and fix text.",
      annotations: referenceToolHints(),
      inputSchema: {
        query: external_exports.string().describe('Keyword or rule id fragment, e.g. "ssh banner" or "SV-257777"'),
        product: external_exports.enum(PRODUCT_IDS).optional().describe("Limit to one benchmark"),
        severity: external_exports.enum(["high", "medium", "low"]).optional().describe("high=CAT I, medium=CAT II, low=CAT III"),
        automation: external_exports.enum(["automated", "manual_only"]).optional(),
        limit: external_exports.number().int().min(1).max(50).optional().describe("Max results per page (default 20)"),
        offset: external_exports.number().int().min(0).optional().describe("Skip this many matches. Pass the next_offset from a previous response to reach results beyond the first page."),
        format: external_exports.enum(["summary", "links"]).optional().describe('"summary" (default) returns each rule inline as JSON. "links" returns MCP resource links, which hosts can render as pickable items the user opens on demand. Not smaller \u2014 the title and severity you need in order to choose are the bulk of either shape \u2014 so choose on how the client presents results, not to save tokens.')
      }
    },
    // Paging exists because it had to: the match set was capped at `limit`
    // while total_matches reported the true count, so a query matching 59
    // rules returned 50 and left 9 unreachable at any limit. Matches are now
    // built in full and then sliced, so the count and reachability agree.
    instrument(SERVER_KEY2, "search_stig", async ({ query, product, severity, automation, limit, offset, format }) => {
      const q = query.trim().toLowerCase();
      if (q.length < 2) return jsonResult2({ error: "Query must be at least 2 characters." });
      const max = Math.min(limit ?? 20, 50);
      const from = offset ?? 0;
      const pool = STIG_CATALOG.filter(
        (r) => (!product || r.product === product) && (!severity || r.severity === severity) && (!automation || r.automation_level === automation)
      );
      const primary = pool.filter(
        (r) => r.sv_id.toLowerCase().includes(q) || r.title.toLowerCase().includes(q)
      );
      const primarySet = new Set(primary);
      const secondary = pool.filter(
        (r) => !primarySet.has(r) && (r.description.toLowerCase().includes(q) || r.check_text.toLowerCase().includes(q))
      );
      const matches = [...primary, ...secondary];
      const page = matches.slice(from, from + max);
      const nextOffset = from + page.length;
      if (format === "links") {
        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                total_matches: matches.length,
                offset: from,
                returned: page.length,
                ...nextOffset < matches.length ? { next_offset: nextOffset } : {},
                tip: "Read a stig://rule/{sv_id} resource, or call get_stig_rule, for check and fix text."
              })
            },
            ...page.map((r) => ({
              type: "resource_link",
              uri: `stig://rule/${r.sv_id}`,
              name: `${r.sv_id} \u2014 ${r.title}`,
              description: `${r.product} \xB7 ${r.severity} (${severityToCat(r.severity)}) \xB7 ${r.category}`,
              mimeType: "application/json"
            }))
          ]
        };
      }
      return jsonResult2({
        total_matches: matches.length,
        offset: from,
        returned: page.length,
        ...nextOffset < matches.length ? { next_offset: nextOffset } : {},
        rules: page.map(summarize),
        tip: "Use get_stig_rule with an sv_id for the full requirement, check text, and fix text."
      });
    })
  );
  server.registerTool(
    "get_stig_rule",
    {
      title: "Get one STIG rule in full",
      description: "Get the complete detail for one DISA STIG rule by its SV id (from search_stig): the requirement discussion, the exact check procedure an assessor runs, the fix text, severity, NIST control mapping, and whether it is SCAP-automatable. Call this when the user needs to implement or verify a specific rule.",
      annotations: referenceToolHints(),
      outputSchema: RULE_OUTPUT,
      inputSchema: {
        sv_id: external_exports.string().describe('Rule id, e.g. "SV-257777r991589_rule" (fragments matched if unique)')
      }
    },
    instrument(SERVER_KEY2, "get_stig_rule", async ({ sv_id }) => {
      const id = sv_id.trim();
      let rule = STIG_BY_SV_ID.get(id);
      if (!rule) {
        const matches = STIG_CATALOG.filter((r) => r.sv_id.includes(id));
        if (matches.length === 1) rule = matches[0];
        else if (matches.length > 1) {
          return jsonResult2({
            error: `"${sv_id}" matches ${matches.length} rules \u2014 be more specific.`,
            candidates: matches.slice(0, 10).map((r) => ({ sv_id: r.sv_id, title: r.title }))
          });
        }
      }
      if (!rule) {
        return jsonResult2({
          error: `No rule matching "${sv_id}". Use search_stig to find rules; ids look like "SV-257777r991589_rule".`
        });
      }
      return structuredResult2({
        ...rule,
        severity_category: severityToCat(rule.severity)
      });
    })
  );
  server.registerTool(
    "list_stig_benchmarks",
    {
      title: "List covered STIG benchmarks",
      description: "List the DISA STIG benchmarks this server covers, with versions, rule counts, and severity breakdowns. Call this first when unsure whether a platform is covered.",
      annotations: referenceToolHints(),
      inputSchema: {}
    },
    instrument(SERVER_KEY2, "list_stig_benchmarks", async () => {
      return jsonResult2({
        benchmarks: PRODUCTS,
        total_rules: STIG_CATALOG.length,
        note: "Coverage is these benchmarks only. For other technologies, DISA publishes the full STIG library at public.cyber.mil/stigs."
      });
    })
  );
  server.registerTool(
    "export_stig_checklist",
    {
      title: "Export a DISA .ckl checklist",
      description: "Generate a DISA STIG Viewer checklist (.ckl XML) for a benchmark, optionally filtered by severity and pre-populated with findings. This is the artifact an assessment actually hands over \u2014 STIG Viewer opens it, eMASS ingests it, and a POA&M is written from it. Rules you do not supply a status for come out as Not_Reviewed. Call this when the user wants a checklist, a scan result recorded, or evidence to submit, rather than just to read a rule.",
      annotations: referenceToolHints(),
      outputSchema: CHECKLIST_OUTPUT,
      inputSchema: {
        product: external_exports.enum(PRODUCT_IDS).describe("Which benchmark to build the checklist from"),
        severity: external_exports.enum(["high", "medium", "low"]).optional().describe("Limit to one severity, e.g. high for a CAT I-only checklist"),
        host_name: external_exports.string().optional().describe("Asset hostname recorded in the checklist"),
        host_ip: external_exports.string().optional(),
        host_fqdn: external_exports.string().optional(),
        findings: external_exports.array(
          external_exports.object({
            sv_id: external_exports.string(),
            status: external_exports.enum(["Open", "NotAFinding", "Not_Applicable", "Not_Reviewed"]).describe("Open = failed, NotAFinding = passed, Not_Applicable = out of scope"),
            finding_details: external_exports.string().optional().describe("What was actually observed"),
            comments: external_exports.string().optional().describe("Assessor justification")
          })
        ).optional().describe("Per-rule results. Anything omitted stays Not_Reviewed \u2014 an unreviewed rule must never be reported as passing.")
      }
    },
    instrument(SERVER_KEY2, "export_stig_checklist", async ({ product, severity, host_name, host_ip, host_fqdn, findings }) => {
      const rules = STIG_CATALOG.filter(
        (r) => r.product === product && (!severity || r.severity === severity)
      );
      if (rules.length === 0) {
        return jsonResult2({
          error: `No rules for product "${product}"${severity ? ` at severity "${severity}"` : ""}. Use list_stig_benchmarks for coverage.`
        });
      }
      const benchmark = rules[0].benchmark;
      const counts = summarizeCkl(rules, findings);
      return structuredResult2({
        benchmark,
        rule_count: rules.length,
        status_counts: counts,
        filename: `${product.replace(/\s+/g, "_")}${severity ? `_${severity}` : ""}.ckl`,
        note: counts.Not_Reviewed > 0 ? `${counts.Not_Reviewed} of ${rules.length} rules are Not_Reviewed. That is the honest default for anything not assessed \u2014 do not mark rules as passing that nobody checked.` : "Every rule carries a reviewed status.",
        ckl: buildCkl({
          rules,
          benchmark,
          asset: { host_name, host_ip, host_fqdn },
          findings
        })
      });
    })
  );
  server.registerResource(
    "rule",
    new ResourceTemplate("stig://rule/{sv_id}", {
      list: () => ({
        resources: STIG_CATALOG.map((r) => ({
          uri: `stig://rule/${r.sv_id}`,
          name: `${r.sv_id} \u2014 ${r.title}`,
          description: `${r.product} \xB7 ${r.severity} (${severityToCat(r.severity)})`,
          mimeType: "application/json"
        }))
      }),
      complete: {
        sv_id: (value) => {
          const v = value.trim().toUpperCase();
          return STIG_CATALOG.map((r) => r.sv_id).filter((id) => id.toUpperCase().startsWith(v)).slice(0, 100);
        }
      }
    }),
    {
      title: "DISA STIG rule",
      description: "One DISA STIG rule with its official check and fix text \u2014 the wording an assessor compares against, so it is quoted rather than paraphrased.",
      mimeType: "application/json"
    },
    async (uri, { sv_id }) => {
      const rule = STIG_BY_SV_ID.get(String(sv_id).trim().toUpperCase());
      return {
        contents: [
          {
            uri: uri.href,
            mimeType: "application/json",
            text: rule ? JSON.stringify(rule) : JSON.stringify({ error: `Unknown STIG rule "${String(sv_id)}".` })
          }
        ]
      };
    }
  );
  server.registerPrompt(
    "harden_host",
    {
      title: "Harden a host to its DISA STIG",
      description: "Produce a reviewable hardening plan for one platform from its DISA STIG, worst-severity first.",
      argsSchema: {
        // The product identifier is a closed set, and it is not the
        // display name — "RHEL 9" is the benchmark title while the
        // argument wants "rhel9". Completing it stops that from being
        // something a caller discovers by getting an error.
        product: completable(
          external_exports.string().describe('Which benchmark to harden against, e.g. "rhel9" or "windows2022".'),
          (value) => {
            const v = value.trim().toLowerCase();
            return PRODUCT_IDS.filter((id) => id.toLowerCase().startsWith(v)).slice(0, 100);
          }
        ),
        topic: external_exports.string().optional().describe('Optional area to focus on, e.g. "ssh" or "auditing".')
      }
    },
    ({ product, topic }) => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: [
              `Build a STIG hardening plan for ${product}${topic ? `, focused on ${topic}` : ""}.`,
              "",
              "Rules, because getting these wrong produces a system that passes nothing:",
              "- Confirm the exact benchmark first with list_stig_benchmarks. RHEL 8 and RHEL 9 rules are not interchangeable.",
              "- Quote the official check and fix text from get_stig_rule verbatim. An assessor compares against DISA's wording; a paraphrase that drifts is a finding.",
              "- Order by severity: CAT I first, then CAT II, then CAT III.",
              "- Page through search_stig with next_offset rather than assuming the first page is everything.",
              "- Show what each fix changes before proposing to run it, and never apply a CAT I change to a live system without explicit confirmation \u2014 several will lock out remote access if applied out of order.",
              "- Prefer producing a reviewable script over ad hoc commands."
            ].join("\n")
          }
        }
      ]
    })
  );
}

// offline/server.ts
var VERSION = "1.0.0";
async function main() {
  const server = new McpServer(
    { name: "mactech-compliance-offline", version: VERSION },
    {
      instructions: [
        CMMC_INSTRUCTIONS,
        "",
        STIG_INSTRUCTIONS,
        "",
        "This is the offline build: the entire corpus is compiled in and no network access is required or attempted. The federal-market tools (SAM.gov, USASpending) are intentionally absent because they cannot work without internet access."
      ].join("\n")
    }
  );
  registerCmmcServer(server);
  registerStigServer(server);
  await server.connect(new StdioServerTransport());
  process.stderr.write(`mactech-compliance-offline ${VERSION} ready (stdio, no network)
`);
}
main().catch((error53) => {
  process.stderr.write(`mactech-compliance-offline failed to start: ${String(error53)}
`);
  process.exit(1);
});
